export function RouteSegment({
  base = "{{base}}",
  current = "{{current}}",
  showParam = {{showParam}},
  accent = "{{accent}}",
}) {
  const segments = [{ label: base, link: true }];
  if (showParam) segments.push({ label: ":size", link: true, dynamic: true });
  return (
    <nav aria-label="Route segments" style={{ fontFamily: "SFMono-Regular, Consolas, monospace", fontSize: 13, color: "#241430" }}>
      <ol style={{ display: "flex", listStyle: "none", padding: "8px 12px", margin: 0, background: "#FAF7F2", borderRadius: 8, width: "fit-content" }}>
        {segments.map((s, i) => (
          <li key={s.label} style={{ display: "flex", alignItems: "center" }}>
            {i > 0 && <span style={{ margin: "0 4px", opacity: .4 }}>/</span>}
            <a href="#" style={{ color: s.dynamic ? accent : "#241430", textDecoration: "none", opacity: s.dynamic ? 1 : .7, fontWeight: s.dynamic ? 700 : 400 }}>{s.label}</a>
          </li>
        ))}
        <li style={{ display: "flex", alignItems: "center" }}>
          <span style={{ margin: "0 4px", opacity: .4 }}>/</span>
          <span aria-current="page" style={{ color: accent, fontWeight: 700 }}>{current}</span>
        </li>
      </ol>
    </nav>
  );
}
